fset:3px}button:disabled{opacity:.45;cursor:default}.solid{color:var(--paper);background:var(--forest)}.solid:hover{background:#235a46}.tools{display:flex;gap:8px;flex-wrap:wrap;margin-top:17px}.tools button[aria-pressed=true]{background:var(--red);color:#fff}.strip{display:flex;justify-content:space-between;align-items:center;gap:15px;margin:18px 0 13px}.pairs{display:flex;gap:7px;flex-wrap:wrap}.pairs button{font-family:Georgia,serif;font-size:19px;min-width:55px;padding:9px 12px}.pairs button[aria-pressed=true]{background:var(--forest);color:var(--paper);box-shadow:0 3px 0 var(--gold)}.adjust{margin:17px 0;padding:17px 0;border-top:1px solid #b9af94;border-bottom:1px solid #b9af94}.adjust label{display:flex;justify-content:space-between;gap:10px;font-size:13px}input[type=range]{width:100%;accent-color:var(--forest);margin:18px 0 6px;min-height:28px;cursor:pointer}.ends{display:flex;justify-content:space-between;color:var(--muted);font-size:11px}.nudge{display:flex;align-items:center;gap:12px;margin-top:12px}.nudge button{width:47px;font-size:20px}.nudge span{font-size:12px;color:var(--muted)}.progress{display:flex;gap:8px;margin-top:24px}.progress span{height:8px;flex:1;background:#c8bda3}.progress span.done{background:var(--forest)}.progress span.current{background:var(--red)}.status{min-height:68px;margin-top:15px;line-height:1.55;font-size:14px}.quality{font-family:Georgia,serif;font-size:45px;margin:12px 0 0}.quality small{font-family:"Trebuchet MS",sans-serif;font-size:12px}.note{color:var(--muted);font-size:12px;line-height:1.7}.lesson{border-top:3px double var(--forest);margin-top:27px;padding-top:17px;display:grid;grid-template-columns:1fr 1fr;gap:30px}.lesson h3{font-family:Georgia,serif;font-weight:normal;font-size:25px;margin:0 0 9px}.lesson p{line-height:1.65;font-size:14px;margin:0}.finished{border:2px solid var(--gold);padding:20px;margin-top:20px;background:#fff9e8}.finished h2{margin-top:0}footer{font-size:12px;line-height:1.9;border-top:1px solid #b9af94;margin-top:27px;padding-top:18px}[hidden]{display:none!important}
