</head><body><main>
<nav><a href="./">← Chloe Reads Jon</a><span class="label">Hand-lettered happiness · Est. today</span></nav>
<header class="mast"><div><span class="label">Five little optical puzzles</span><h1>Letterspace<br><em>Sign Shop.</em></h1></div><p class="intro">Good letters can still make a bad sign.<br>Bring five shop signs into balance, one tiny space at a time. You’re the painter. The alphabet is being difficult.</p></header>
<div class="work"><section aria-label="Sign painting workbench">
<div class="board"><img id="artwork" alt="An original painted sign workshop: an ivory wooden board surrounded by lettering brushes and gold leaf."><svg id="sign" viewBox="0 0 1000 667" role="img" aria-label="Interactive lettering sign"><g id="tracing" class="ink ghost" hidden></g><g id="letters" class="ink"></g><g id="marks"></g><text x="500" y="407" text-anchor="middle" fill="#93612a" font-family="Georgia,serif" font-size="15" letter-spacing="5" id="subtitle"></text></svg></div>
<div class="tools"><button id="before" aria-pressed="false">See the original spacing</button><button id="trace" aria-pressed="false">Apprentice tracing</button><button id="print">Print this sign</button></div>
<div class="strip"><span class="label">Select a letter pair</span><span class="label" id="counter">Order 1 / 5</span></div>
<div class="pairs" id="pairs" role="group" aria-label="Letter pairs"></div>
<div class="adjust"><label for="gap"><span id="gapLabel"></span><output id="gapValue" for="gap"></output></label><input id="gap" type="range" min="-18" max="22" step="1" value="0"><div class="ends"><span>← Bring them closer</span><span>Give them room →</span></div><div class="nudge"><button id="minus" aria-label="Reduce selected gap by one">−</button><button id="plus" aria-label="Increase selected gap by one">+</button><span>Arrow keys on the slider work too.</span></div></div>
<p class="note">The highlighted rule shows your selected pair. Adjust until the word feels even, then ask the foreman. No clock, and no need to be perfect.</p>
</section>
<aside class="receipt"><span class="label order">Today's paint orders</span><h2 id="client"></h2><p id="brief"></p><div class="progress" id="progress" aria-label="Order progress"></div><div class="quality" id="quality">— <small>optical match</small></div><div class="status" id="status" role="status" aria-live="polite">Trust your eyes. The ruler is only an assistant.</div><div class="tools"><button id="check" class="solid">Ask the foreman</button><button id="next" hidden>Hang this sign →</button><button id="reset">Reset this order</button></div><p class="note">The foreman compares your spacing with one hand-tuned example, not a universal “correct” answer. 85% is close enough to hang. Tracing is welcome!</p><div class="finished" id="finished" hidden><h2>Open for business.</h2><p>Five signs balanced. You now know why “just put a space between them” is not quite a design system.</p><button id="restart">Paint them again</button></div></aside></div>
<section class="lesson"><div><h3>Measure the empty shapes.</h3><p>Kerning is adjusting the space between a specific pair of letters. An A and a V have sloping sides: their empty corners can tuck together. Round letters make very different pockets of space.</p></div><div><h3>Even numbers ≠ even rhythm.</h3><p>Tracking spreads a whole word out equally. Kerning treats troublesome neighbours individually. Look for a steady visual rhythm, not identical distances. Squinting is a perfectly respectable design tool.</p></div></section>
<footer>Inspired by Jon’s <a href="?source=1">Letterhead Fonts: Rare and Unique Typefaces for Artists</a> (2004).<br>Original workshop illustration created for this game. A typography teaching toy; all five fictional shops operate entirely in your browser.</footer>
</main>
<script>
const orders=[
 {word:'WAVY',name:'The Wavy Boat Club',sub:'SMALL BOATS · BIG WAVES',brief:'The sloping letters have drifted apart. Bring their empty corners together without letting the ink collide.',target:[-12,-14,-8],start:[17,14,16]},
 {word:'AVATAR',name:'Avatar Adventure Outfitters',sub:'GEAR FOR IMAGINARY JOURNEYS',brief:'Three A’s, one very troublesome V. The overhanging T needs attention too. Try to make the gaps feel like one rhythm.',target:[-14,-13,-10,-11,-2],start:[12,3,17,9,15]},
 {word:'TOYBOX',name:'Nathan’s Toybox',sub:'SERIOUSLY GOOD PLAY',brief:'T has a roof; O is a curve; Y is all elbows. Find the little pocket beneath T, then settle its neighbours.',target:[-10,-8,-4,-2,-4],start:[19,14,-15,18,17]},
 {word:'COCOA',name:'The Cocoa Corner',sub:'WARM MUGS · WARM HEARTS',brief:'Round letters can seem farther apart than a ruler suggests. Resist squeezing every pair by the same amount.',target:[-3,-3,-3,-6],start:[16,-15,18,13]},
 {word:'NATHAN',name:'Nathan’s Grand Garage',sub:'TINY CARS · GREAT ADVENTURES',brief:'The final commission: a nameplate for a very grand garage. Compare straight-sided neighbours with T’s open corners.',target:[-3,-10,-7,-3,-3],start:[16,19,12,-15,20]}
];
let round=0,selected=0,gaps=[],showBefore=false,showTrace=false,completed=false;
const $=id=>document.getElementById(id), ns='http://www.w3.org/2000/svg';
const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');ctx.font='bold 100px Georgia';
function layout(values){const chars=[...orders[round].word],widths=chars.map(c=>ctx.measureText(c).width),total=widths.reduce((a,b)=>a+b,0)+values.reduce((a,b)=>a+b,0);let x=(1000-total)/2;return chars.map((c,i)=>{const p={c,x,w:widths[i]};x+=widths[i]+(values[i]||0);return p})}
function node(tag,attrs,text){const n=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));if(text)n.textContent=text;return n}
function paint(group,values){group.replaceChildren(...layout(values).map(p=>node('text',{x:p.x,y:343,'font-size':100},p.c)))}
function render(){paint($('letters'),showBefore?orders[round].start:gaps);paint($('tracing'),orders[round].target);$('tracing').toggleAttribute('hidden',!showTrace||showBefore);$('tracing').style.display=showTrace&&!showBefore?'':'none';const ps=layout(gaps),a=ps[selected],b=ps[selected+1];$('marks').replaceChildren();if(!showBefore&&!completed){const x1=a.x+a.w*.55,x2=b.x+b.w*.45;$('marks').append(node('line',{x1,y1:362,x2,y2:362,stroke:'#a43e2e','stroke-width':2}),node('circle',{cx:x1,cy:362,r:3,fill:'#a43e2e'}),node('circle',{cx:x2,cy:362,r:3,fill:'#a43e2e'}))}
$('gap').value=gaps[selected];$('gapValue').textContent=(gaps[selected]>0?'+':'')+gaps[selected]+' units';$('gapLabel').textContent='Space between '+a.c+' and '+b.c;$('pairs').querySelectorAll('button').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===selected)));$('before').setAttribute('aria-pressed',String(showBefore));$('trace').setAttribute('aria-pressed',String(showTrace));}
function clearVerdict(){if(completed)return;$('quality').innerHTML='— <small>optical match</small>';$('next').hidden=true;$('status').textContent='A fresh brushstroke. Ask the foreman when you’re ready.';}
function change(value){if(completed)return;gaps[selected]=Math.max(-18,Math.min(22,Number(value)));showBefore=false;clearVerdict();render()}
function load(){gaps=[...orders[round].start];selected=0;showBefore=false;showTrace=false;completed=false;$('finished').hidden=true;$('client').textContent=orders[round].name;$('brief').textContent=orders[round].brief;$('subtitle').textContent=orders[round].sub;$('counter').textContent='Order '+(round+1)+' / 5';$('pairs').replaceChildren(...gaps.map((_,i)=>{const b=document.createElement('button');b.textContent=orders[round].word.slice(i,i+2);b.setAttribute('aria-label','Adjust space between '+orders[round].word[i]+' and '+orders[round].word[i+1]);b.onclick=()=>{selected=i;render()};return b}));$('progress').replaceChildren(...orders.map((_,i)=>{const s=document.createElement('span');s.className=i<round?'done':i===round?'current':'';return s}));$('quality').innerHTML='— <small>optical match</small>';$('status').textContent='Trust your eyes. The ruler is only an assistant.';$('next').hidden=true;['gap','minus','plus','check','reset','trace','before'].forEach(id=>$(id).disabled=false);render()}
$('gap').oninput=e=>change(e.target.value);$('minus').onclick=()=>change(gaps[selected]-1);$('plus').onclick=()=>change(gaps[selected]+1);
$('trace').onclick=()=>{showTrace=!showTrace;showBefore=false;render()};
$('before').onclick=()=>{showBefore=!showBefore;render()};
$('check').onclick=()=>{showBefore=false;render();const error=gaps.reduce((sum,v,i)=>sum+Math.abs(v-orders[round].target[i]),0)/gaps.length;const score=Math.max(0,Math.round(100-error*4));$('quality').innerHTML=score+'% <small>optical match</small>';if(score>=85){$('status').textContent='That has a lovely rhythm. Ready for the shopfront!';$('next').hidden=false}else{const worst=gaps.map((v,i)=>({i,d:v-orders[round].target[i]})).sort((a,b)=>Math.abs(b.d)-Math.abs(a.d))[0];$('status').textContent='Try '+orders[round].word.slice(worst.i,worst.i+2)+': '+(worst.d>0?'bring these neighbours closer.':'give these neighbours a little more room.')+' Or switch on apprentice tracing to compare.';$('next').hidden=true}};
$('next').onclick=()=>{if(round<orders.length-1){round++;load();$('client').scrollIntoView({block:'nearest',behavior:'instant'})}else{completed=true;$('finished').hidden=false;$('next').hidden=true;$('status').textContent='The whole street is ready to open.';$('progress').querySelectorAll('span').forEach(s=>s.className='done');['gap','minus','plus','check','reset'].forEach(id=>$(id).disabled=true);render();$('finished').scrollIntoView({block:'nearest',behavior:'instant'})}};
$('reset').onclick=load;$('restart').onclick=()=>{round=0;load()};$('print').onclick=()=>{const before=showBefore,trace=showTrace;showBefore=false;showTrace=false;render();$('marks').style.display='none';window.print();$('marks').style.display='';showBefore=before;showTrace=trace;render()};
$('artwork').src='data:image/webp;base64,';
load();
</script></body></html>
